$files = @("public\en\clipping\index.html", "public\en\multiviewer\index.html")

foreach ($f in $files) {
    if (Test-Path $f) {
        $content = Get-Content -Path $f -Raw -Encoding UTF8
        foreach ($key in $translations.Keys) {
            $content = $content.Replace($key, $translations[$key])
        }
        $utf8NoBom = New-Object System.Text.UTF8Encoding($false)
        [System.IO.File]::WriteAllText("c:\Users\gmass\.gemini\antigravity\scratch\3wayWWW\3waywww\" + $f, $content, $utf8NoBom)
        Write-Host "Updated $f"
    }
}
